const { setHumanTakeover, sbRequest, saveMessage } = require('/home/node/scripts/cvpro-helpers.js');
const { conversationId, customerId, agentEmail } = $input.first().json.body;

await setHumanTakeover($http, conversationId, agentEmail);

const customers = await sbRequest($http, 'GET', `/rest/v1/customers?id=eq.${customerId}&select=phone_number,full_name&limit=1`);
const customer = customers?.[0];
const handoffMsg = 'شكراً لتواصلك مع CVPro.ae! سيتم تحويلك إلى أحد خبرائنا الذين سيردون عليك خلال دقائق. 😊';

await saveMessage($http, conversationId, 'outbound', handoffMsg, { is_ai_generated: false });

if (customer?.phone_number) {
  await $http.request({
    method: 'POST',
    url: `https://graph.facebook.com/v21.0/${process.env.WHATSAPP_PHONE_NUMBER_ID}/messages`,
    headers: { Authorization: `Bearer ${process.env.WHATSAPP_ACCESS_TOKEN}`, 'Content-Type': 'application/json' },
    body: { messaging_product: 'whatsapp', to: customer.phone_number, type: 'text', text: { body: handoffMsg } },
  });
}

return [{ json: { success: true, conversationId, assignedTo: agentEmail, notifiedVia: 'supabase_realtime' } }];
